export const defaultRules={event:30,cyclical:180,structural:null};
const num=v=>v!==''&&v!=null&&Number.isFinite(Number(v))?Number(v):null;
export function ageDays(value,now=new Date()){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return null;const t=Date.parse(value+'T00:00:00Z');if(!Number.isFinite(t)||new Date(t).toISOString().slice(0,10)!==value)return null;const age=(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate())-t)/86400000;return age<0?null:age;}
export function retention(row,rules=defaultRules,now=new Date()){const age=ageDays(row.asOf,now);if(row.status==='retired'||age===null)return 0;if(row.kind==='structural')return 1;const days=rules[row.kind];return Number.isFinite(days)&&days>0?2**(-age/days):0;}
export function pressure(assumptions,observations=[],rules=defaultRules,now=new Date()){return assumptions.map(a=>{const rows=observations.filter(r=>r.assumptionId===a.id&&r.status!=='retired');const total=direction=>rows.filter(r=>r.direction===direction).reduce((s,r)=>s+retention(r,rules,now),0);return {id:a.id,claim:a.claim,rows,support:total('support'),challenge:total('challenge'),unresolved:rows.filter(r=>r.direction==='challenge').length,targets:['pillar','signpost','estimate','risk'].map(type=>({type,support:rows.filter(r=>r.targetType===type&&r.direction==='support').length,challenge:rows.filter(r=>r.targetType===type&&r.direction==='challenge').length}))};});}
export function falsification(row,now=new Date()){const current=num(row.current),threshold=num(row.threshold),age=ageDays(row.asOf,now);if(current===null||threshold===null||age===null||!row.source||!row.unit||!row.period)return {status:'Missing comparable observation',distance:null};const distance=row.operator==='gte'?threshold-current:current-threshold;return {status:age>90?'Observation older than 90 days':distance<=0?'Threshold reached · review required':'Threshold not reached',distance,age};}
export function variant(row,now=new Date()){const view=num(row.view),market=num(row.market),age=ageDays(row.asOf,now);if(view===null||market===null||age===null||!row.source||!row.period||!row.unit||row.baselineType==='unknown')return {status:'Comparable market baseline needed',delta:null};return {status:age>90?'Baseline older than 90 days':'Comparable stated estimates',delta:view-market,percent:market===0?null:(view-market)/Math.abs(market)*100};}
export function divergence(position={},pillars=[],now=new Date()){const weight=num(position.weight),benchmark=num(position.benchmarkWeight),age=ageDays(position.asOf,now);if(weight===null||age===null||!position.portfolio)return {active:null,questions:['Record a dated portfolio weight to assess alignment.']};if(age>30)return {active:null,questions:['Refresh holdings: this snapshot is older than 30 days.']};const active=benchmark===null||!position.benchmark?null:weight-benchmark;const support=pillars.reduce((s,p)=>s+p.support,0),challenge=pillars.reduce((s,p)=>s+p.challenge,0),known=pillars.some(p=>p.rows.length);let questions=[];if(active!==null&&active<=0&&position.conviction==='high')questions.push('High conviction with a nonpositive active weight: is valuation, risk budget or a mandate constraint the explanation?');if(weight>0&&known&&challenge>support)questions.push('Challenging evidence outweighs supporting evidence under the saved decay rules: does the recorded position rationale still hold?');if(weight>0&&position.conviction==='low')questions.push('A positive holding with low case conviction: what justifies maintaining this exposure?');if(active===null)questions.push('Add a named benchmark weight to compare active exposure.');if(!known)questions.push('No classified evidence observations yet; evidence direction is unknown.');if(!questions.length)questions.push('No rule-based divergence flagged. This is not a position endorsement.');return {active,questions};}
