export function workItems(meetings=[],commands=[],activities=[],manual=[]){
 const ids=new Set(meetings.map(j=>j.id)),byId=new Map(commands.map(j=>[j.id,j]));
 const bucket=(status,error)=>status==='cancelled'?'closed':error||status==='failed'?'failed':['attention','needs_auth','pending_review'].includes(status)?'needs_me':status==='done'?'ready':'running';
 return [...manual.map(j=>({id:j.id,ticker:j.ticker,kind:'Manual meeting pack',manual:true,bucket:bucket(j.status,j.error),status:j.status==='done'?'Pack ready':`${j.status}: ${j.step||'queued'}`,error:j.error,job:j})),...meetings.map(j=>{const c=byId.get(j.id),status=j.prep_status||c?.collection?.status||j.status;return {id:j.id,ticker:j.ticker,kind:'Meeting pack',bucket:bucket(status,j.prep_error||j.error),status:j.prep_status==='done'?'Pack ready':j.prep_status?`Preparation: ${j.prep_step||j.prep_status}`:c?.collection?`Collection: ${c.collection.status}`:'Waiting for source preparation',error:j.prep_error||j.error||c?.collection?.issue,job:j};}),
 ...commands.filter(j=>!ids.has(j.id)).map(j=>({id:j.id,ticker:j.ticker,kind:'Research command',bucket:bucket(j.reports?.some(r=>r.has_report)?'pending_review':j.collection?.status||j.status,j.error||j.reports?.find(r=>r.error)?.error),status:j.reports?.some(r=>r.has_report)?'Recap available':j.collection?.status||j.status,error:j.error||j.collection?.issue,job:j})),
 ...activities.map(a=>({id:a.id,ticker:a.ticker,kind:'Analyst recap',bucket:bucket(a.status,a.error),status:a.status.replaceAll('_',' '),error:a.error,activity:a}))];
}
